assignments.value:
={{ 
  const required = ['company_name', 'industry', 'contact_name', 'email', 'challenges', 'goals'];
  const missing = required.filter(field => !$json[field] || $json[field].toString().trim() === '');
  return missing.length > 0 ? missing : null;
}}

