assignments.value:
={{ {
  id: $workflow.id + '-' + $runIndex + '-' + Date.now(),
  email: $json.email?.toLowerCase()?.trim(),
  subject: $json.subject?.trim(),
  message: $json.message?.trim(),
  customer_name: $json.customer_name?.trim(),
  priority: $json.priority || 'medium',
  created_at: new Date().toISOString(),
  customer_history: $json.customer_history || 'No history available'
} }}

